export function UI({
  chrome = {{chrome}},
  appName = "{{appName}}",
  density = "{{density}}",
  accent = "{{accent}}",
}) {
  const compact = density === "compact";
  return (
    <div style={{ width: "100%", maxWidth: 320, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#241430aa" }}>
      {chrome && <div style={{ padding: "8px 12px", color: "#fff", fontWeight: 700, background: accent }}>{appName}</div>}
      <div style={{ display: "flex" }}>
        {chrome && (
          <div style={{ width: 34, background: "#24143011", padding: 8, display: "flex", flexDirection: "column", gap: 6 }}>
            <span style={{ width: 16, height: 16, borderRadius: 4, background: "#24143033" }} />
            <span style={{ width: 16, height: 16, borderRadius: 4, background: "#24143033" }} />
            <span style={{ width: 16, height: 16, borderRadius: 4, background: "#24143033" }} />
          </div>
        )}
        <div style={{ flex: 1, padding: compact ? 5 : 10, display: "flex", gap: compact ? 4 : 8 }}>
          <div style={{ flex: 1, height: compact ? 34 : 50, background: "#fff", border: "1px solid #24143022", borderRadius: 8 }} />
          <div style={{ flex: 1, height: compact ? 34 : 50, background: "#fff", border: "1px solid #24143022", borderRadius: 8 }} />
        </div>
      </div>
      <p style={{ margin: 0, padding: "8px 10px" }}>The whole visual and interactive layer &mdash; every screen and control together is the UI</p>
    </div>
  );
}
